  // Three exemplar cards
  const examples = [
    { name: "ChatGPT", stat: "Fastest-growing app in history", detail: "Strong PMF among students and developers" },
    { name: "Midjourney", stat: "Hundreds of $M in revenue", detail: "Team of just 11 people" },
    { name: "Character.ai", stat: "2 hrs avg. session time", detail: "Pioneered AI entertainment & companionship" },
  ];

  examples.forEach((ex, i) => {
    const y = 1.6 + i * 1.25;
    const x = 4.5;
