      x: x, y: y, w: 0.07, h: 1.05,
      fill: { color: C.green },
    });
    s.addText(ex.name, {
      x: x + 0.25, y: y + 0.08, w: 4.3, h: 0.3,
      fontSize: 14, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
    });
    s.addText(ex.stat, {
      x: x + 0.25, y: y + 0.38, w: 4.3, h: 0.25,
      fontSize: 12, fontFace: FONT_B, color: C.green, bold: true, margin: 0,
    });
    s.addText(ex.detail, {
      x: x + 0.25, y: y + 0.63, w: 4.3, h: 0.3,
      fontSize: 11, fontFace: FONT_B, color: C.grayDark, margin: 0,
    });
  });
}

// ============================================================
// SLIDE 4 — Retention Gap (bar chart)
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.white };

  s.addText("AI-First Apps Show 14% Median Retention\nvs. 51% for Incumbents", {
    x: 0.8, y: 0.35, w: 8.4, h: 0.95,
    fontSize: 24, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
  });

  // Incumbents chart (left)
  s.addText("INCUMBENTS  (Median 51%)", {
    x: 0.5, y: 1.35, w: 4.3, h: 0.3,
    fontSize: 11, fontFace: FONT_B, color: C.blue, bold: true, margin: 0,
  });

  const incumbents = [
    ["WhatsApp", 85], ["Instagram", 64], ["YouTube", 64], ["TikTok", 60],
    ["Snapchat", 51], ["Roblox", 41], ["Tinder", 34], ["Candy Crush", 32], ["Duolingo", 30],
  ];
  const aiFirst = [
    ["Character.ai", 41], ["Runway", 27], ["Remini", 14], ["ChatGPT", 14], ["Lensa", 12],
  ];

  const barH = 0.3;
  const gap = 0.08;
  const maxBarW = 3.0;
  const startY = 1.7;

  incumbents.forEach(([name, val], i) => {
    const y = startY + i * (barH + gap);
    s.addText(name, {
      x: 0.5, y: y, w: 1.2, h: barH,
      fontSize: 9, fontFace: FONT_B, color: C.grayDark, align: "right", valign: "middle", margin: 0,
    });
    const bw = (val / 100) * maxBarW;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 1.8, y: y + 0.03, w: bw, h: barH - 0.06,
      fill: { color: val === 51 ? C.blue : "6BA4DC" },
    });
    s.addText(`${val}%`, {
      x: 1.8 + bw + 0.08, y: y, w: 0.5, h: barH,
      fontSize: 9, fontFace: FONT_B, color: C.grayDark, valign: "middle", margin: 0,
    });
  });

  // AI-First chart (right)
  s.addText("AI-FIRST  (Median 14%)", {
    x: 5.5, y: 1.35, w: 4.0, h: 0.3,
    fontSize: 11, fontFace: FONT_B, color: C.red, bold: true, margin: 0,
  });

  aiFirst.forEach(([name, val], i) => {
