const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Sequoia Capital";
pres.title = "Generative AI's Act Two: From Technology Hammer to Real Value";

// Palette: Midnight Executive adapted for Sequoia
const C = {
  dark: "1A1F36",
  darkAcc: "252B48",
  green: "00C853",
  white: "FFFFFF",
  light: "F5F7FA",
  gray: "8892A0",
  grayDark: "4A5568",
  accent: "00B87C",
  red: "E53E3E",
  blue: "3182CE",
  teal: "0D9488",
  orange: "ED8936",
};

const FONT_H = "Georgia";
const FONT_B = "Calibri";

const mkShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

// ============================================================
// SLIDE 1 — Title
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.dark };
  // Subtle accent bar at top
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.green } });

  s.addText("GENERATIVE AI'S ACT TWO", {
    x: 0.8, y: 1.2, w: 8.4, h: 1.0,
    fontSize: 40, fontFace: FONT_H, color: C.white, bold: true, charSpacing: 2,
    margin: 0,
  });
  s.addText("From Technology Hammer to Real Value", {
    x: 0.8, y: 2.2, w: 8.4, h: 0.7,
    fontSize: 22, fontFace: FONT_B, color: C.green, italic: true, margin: 0,
  });
  s.addText("Sequoia Capital  |  September 2023", {
    x: 0.8, y: 3.4, w: 8.4, h: 0.5,
    fontSize: 13, fontFace: FONT_B, color: C.gray, margin: 0,
  });
  s.addText("Sonya Huang, Pat Grady and GPT-4", {
    x: 0.8, y: 3.85, w: 8.4, h: 0.5,
    fontSize: 12, fontFace: FONT_B, color: C.gray, margin: 0,
  });
}

// ============================================================
// SLIDE 2 — Decades of Convergence
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.light };

  s.addText("Six Decades of Technological Progress\nConverged to Enable Generative AI", {
    x: 0.8, y: 0.35, w: 8.4, h: 0.95,
    fontSize: 24, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
  });

  const waves = [
    { label: "6 DECADES", title: "Moore's Law", desc: "Delivered the compute horsepower to process exaflops of data", color: C.blue, w: 8.0 },
    { label: "4 DECADES", title: "The Internet", desc: "Accelerated by COVID, produced trillions of tokens of training data", color: C.teal, w: 6.0 },
    { label: "2 DECADES", title: "Mobile & Cloud", desc: "Put a supercomputer in every human's palm", color: C.green, w: 4.0 },
  ];

  waves.forEach((wave, i) => {
    const y = 1.7 + i * 1.15;
    // Bar
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.8, y: y, w: wave.w, h: 0.85,
      fill: { color: wave.color, transparency: 12 },
    });
    // Left accent
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.8, y: y, w: 0.07, h: 0.85,
      fill: { color: wave.color },
    });
    s.addText(wave.label, {
      x: 1.1, y: y + 0.05, w: 1.5, h: 0.35,
      fontSize: 11, fontFace: FONT_B, color: wave.color, bold: true, margin: 0,
    });
    s.addText(wave.title, {
      x: 1.1, y: y + 0.32, w: 2.5, h: 0.35,
      fontSize: 16, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
    });
    s.addText(wave.desc, {
      x: 3.6, y: y + 0.15, w: wave.w - 3.0, h: 0.55,
      fontSize: 12, fontFace: FONT_B, color: C.grayDark, margin: 0, valign: "middle",
    });
  });

  s.addText("ChatGPT's launch ignited a Cambrian explosion of innovation not seen since the early internet.", {
    x: 0.8, y: 5.0, w: 8.4, h: 0.4,
    fontSize: 11, fontFace: FONT_B, color: C.gray, italic: true, margin: 0,
  });
}

// ============================================================
// SLIDE 3 — GenAI Outpaces SaaS
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.white };

  s.addText("GenAI Startups Surpassed $1B Revenue\nFaster Than SaaS Ever Did", {
    x: 0.8, y: 0.35, w: 8.4, h: 0.95,
    fontSize: 24, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
  });

  // Big stat
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 1.6, w: 3.2, h: 1.6,
    fill: { color: C.dark }, shadow: mkShadow(),
  });
  s.addText(">$1B", {
    x: 0.8, y: 1.65, w: 3.2, h: 0.9,
    fontSize: 48, fontFace: FONT_H, color: C.green, bold: true, align: "center", margin: 0,
  });
  s.addText("startup revenue in months,\nnot years", {
    x: 0.8, y: 2.5, w: 3.2, h: 0.6,
    fontSize: 12, fontFace: FONT_B, color: C.gray, align: "center", margin: 0,
  });

  // Three exemplar cards
  const examples = [
    { name: "ChatGPT", stat: "Fastest-growing app in history", detail: "Strong PMF among students and developers" },
    { name: "Midjourney", stat: "Hundreds of $M in revenue", detail: "Team of just 11 people" },
    { name: "Character.ai", stat: "2 hrs avg. session time", detail: "Pioneered AI entertainment & companionship" },
  ];

  examples.forEach((ex, i) => {
    const y = 1.6 + i * 1.25;
    const x = 4.5;
    s.addShape(pres.shapes.RECTANGLE, {
      x: x, y: y, w: 4.8, h: 1.05,
      fill: { color: C.light }, shadow: mkShadow(),
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: x, y: y, w: 0.07, h: 1.05,
      fill: { color: C.green },
    });
    s.addText(ex.name, {
      x: x + 0.25, y: y + 0.08, w: 4.3, h: 0.3,
      fontSize: 14, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
    });
    s.addText(ex.stat, {
      x: x + 0.25, y: y + 0.38, w: 4.3, h: 0.25,
      fontSize: 12, fontFace: FONT_B, color: C.green, bold: true, margin: 0,
    });
    s.addText(ex.detail, {
      x: x + 0.25, y: y + 0.63, w: 4.3, h: 0.3,
      fontSize: 11, fontFace: FONT_B, color: C.grayDark, margin: 0,
    });
  });
}

// ============================================================
// SLIDE 4 — Retention Gap (bar chart)
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.white };

  s.addText("AI-First Apps Show 14% Median Retention\nvs. 51% for Incumbents", {
    x: 0.8, y: 0.35, w: 8.4, h: 0.95,
    fontSize: 24, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
  });

  // Incumbents chart (left)
  s.addText("INCUMBENTS  (Median 51%)", {
    x: 0.5, y: 1.35, w: 4.3, h: 0.3,
    fontSize: 11, fontFace: FONT_B, color: C.blue, bold: true, margin: 0,
  });

  const incumbents = [
    ["WhatsApp", 85], ["Instagram", 64], ["YouTube", 64], ["TikTok", 60],
    ["Snapchat", 51], ["Roblox", 41], ["Tinder", 34], ["Candy Crush", 32], ["Duolingo", 30],
  ];
  const aiFirst = [
    ["Character.ai", 41], ["Runway", 27], ["Remini", 14], ["ChatGPT", 14], ["Lensa", 12],
  ];

  const barH = 0.3;
  const gap = 0.08;
  const maxBarW = 3.0;
  const startY = 1.7;

  incumbents.forEach(([name, val], i) => {
    const y = startY + i * (barH + gap);
    s.addText(name, {
      x: 0.5, y: y, w: 1.2, h: barH,
      fontSize: 9, fontFace: FONT_B, color: C.grayDark, align: "right", valign: "middle", margin: 0,
    });
    const bw = (val / 100) * maxBarW;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 1.8, y: y + 0.03, w: bw, h: barH - 0.06,
      fill: { color: val === 51 ? C.blue : "6BA4DC" },
    });
    s.addText(`${val}%`, {
      x: 1.8 + bw + 0.08, y: y, w: 0.5, h: barH,
      fontSize: 9, fontFace: FONT_B, color: C.grayDark, valign: "middle", margin: 0,
    });
  });

  // AI-First chart (right)
  s.addText("AI-FIRST  (Median 14%)", {
    x: 5.5, y: 1.35, w: 4.0, h: 0.3,
    fontSize: 11, fontFace: FONT_B, color: C.red, bold: true, margin: 0,
  });

  aiFirst.forEach(([name, val], i) => {
    const y = startY + i * (barH + gap);
    s.addText(name, {
      x: 5.5, y: y, w: 1.2, h: barH,
      fontSize: 9, fontFace: FONT_B, color: C.grayDark, align: "right", valign: "middle", margin: 0,
    });
    const bw = (val / 100) * maxBarW;
    s.addShape(pres.shapes.RECTANGLE, {
      x: 6.8, y: y + 0.03, w: bw, h: barH - 0.06,
      fill: { color: val === 14 ? C.red : "F08080" },
    });
    s.addText(`${val}%`, {
      x: 6.8 + bw + 0.08, y: y, w: 0.5, h: barH,
      fontSize: 9, fontFace: FONT_B, color: C.grayDark, valign: "middle", margin: 0,
    });
  });

  // Median comparison callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 5.05, w: 8.4, h: 0.45,
    fill: { color: C.light },
  });
  s.addText([
    { text: "3.6× retention gap  ", options: { bold: true, color: C.red, fontSize: 13, fontFace: FONT_B } },
    { text: "— AI-first apps retain users at roughly one-third the rate of established consumer apps", options: { fontSize: 12, fontFace: FONT_B, color: C.grayDark } },
  ], { x: 1.0, y: 5.05, w: 8.0, h: 0.45, valign: "middle", margin: 0 });
}

// ============================================================
// SLIDE 5 — Incumbent Monthly Usage
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.white };

  s.addText("YouTube Leads Incumbents at 85%\nMonthly Active Usage", {
    x: 0.8, y: 0.35, w: 8.4, h: 0.95,
    fontSize: 24, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
  });

  const apps = [
    ["YouTube", 85], ["Instagram", 73], ["TikTok", 69], ["Snapchat", 67],
    ["WhatsApp", 63], ["Roblox", 61], ["Tinder", 54], ["Duolingo", 50], ["Candy Crush", 48],
  ];

  s.addChart(pres.charts.BAR, [{
    name: "Monthly Active Usage",
    labels: apps.map(a => a[0]),
    values: apps.map(a => a[1]),
  }], {
    x: 0.8, y: 1.5, w: 8.4, h: 3.5,
    barDir: "bar",
    chartColors: ["3182CE"],
    chartArea: { fill: { color: C.white } },
    catAxisLabelColor: C.grayDark,
    catAxisLabelFontSize: 10,
    valAxisLabelColor: C.gray,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.dark,
    dataLabelFontSize: 10,
    showLegend: false,
    valAxisMaxVal: 100,
  });

  s.addText("Median: 63% monthly active usage — the benchmark AI apps must clear.", {
    x: 0.8, y: 5.1, w: 8.4, h: 0.4,
    fontSize: 12, fontFace: FONT_B, color: C.gray, italic: true, margin: 0,
  });
}

// ============================================================
// SLIDE 6 — Act 1 vs Act 2
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.light };

  s.addText("Act 1 Was Technology-Out;\nAct 2 Is Customer-Back", {
    x: 0.8, y: 0.35, w: 8.4, h: 0.95,
    fontSize: 24, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
  });

  // Act 1 column
  const colW = 4.0;
  const col1X = 0.8;
  const col2X = 5.2;
  const topY = 1.5;
  const colH = 3.6;

  // Act 1 card
  s.addShape(pres.shapes.RECTANGLE, {
    x: col1X, y: topY, w: colW, h: colH,
    fill: { color: C.white }, shadow: mkShadow(),
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: col1X, y: topY, w: colW, h: 0.5,
    fill: { color: C.red },
  });
  s.addText("ACT 1: TECHNOLOGY-OUT", {
    x: col1X, y: topY, w: colW, h: 0.5,
    fontSize: 13, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });

  const act1Items = [
    "Foundation models as the entire solution",
    "Novelty demos & lightweight wrappers",
    "Cool technology seeking a problem",
    "Poor user retention (14% median)",
    "Thin competitive moats",
  ];

  s.addText(act1Items.map((t, i) => ({
    text: t,
    options: { bullet: true, breakLine: i < act1Items.length - 1, fontSize: 12, fontFace: FONT_B, color: C.grayDark },
  })), {
    x: col1X + 0.3, y: topY + 0.7, w: colW - 0.6, h: 2.7,
    paraSpaceAfter: 8, valign: "top",
  });

  // Act 2 card
  s.addShape(pres.shapes.RECTANGLE, {
    x: col2X, y: topY, w: colW, h: colH,
    fill: { color: C.white }, shadow: mkShadow(),
  });
  s.addShape(pres.shapes.RECTANGLE, {
    x: col2X, y: topY, w: colW, h: 0.5,
    fill: { color: C.green },
  });
  s.addText("ACT 2: CUSTOMER-BACK", {
    x: col2X, y: topY, w: colW, h: 0.5,
    fontSize: 13, fontFace: FONT_B, color: C.white, bold: true, align: "center", valign: "middle", margin: 0,
  });

  const act2Items = [
    "Foundation models as a piece of a comprehensive solution",
    "New editing interfaces for stickier workflows",
    "Multi-modal, end-to-end problem solving",
    "Solving real human problems",
    "Workflow-integrated & defensible",
  ];

  s.addText(act2Items.map((t, i) => ({
    text: t,
    options: { bullet: true, breakLine: i < act2Items.length - 1, fontSize: 12, fontFace: FONT_B, color: C.grayDark },
  })), {
    x: col2X + 0.3, y: topY + 0.7, w: colW - 0.6, h: 2.7,
    paraSpaceAfter: 8, valign: "top",
  });

  // Exemplars
  s.addText([
    { text: "Act 2 Exemplars: ", options: { bold: true, color: C.dark, fontSize: 12, fontFace: FONT_B } },
    { text: "Harvey (legal LLMs)  •  Glean (enterprise search)  •  Character (digital companions)  •  Ava (companionship)", options: { fontSize: 12, fontFace: FONT_B, color: C.grayDark } },
  ], {
    x: 0.8, y: 5.2, w: 8.4, h: 0.35,
    margin: 0,
  });
}

// ============================================================
// SLIDE 7 — Market Map Evolution
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.white };

  s.addText("Market Map Reorganized\nby Use Case, Not Model Modality", {
    x: 0.8, y: 0.35, w: 8.4, h: 0.95,
    fontSize: 24, fontFace: FONT_H, color: C.dark, bold: true, margin: 0,
  });

  // Before / After comparison
  const bx = 0.8, ax = 5.2, cw = 4.0;

  // Before card
  s.addShape(pres.shapes.RECTANGLE, {
    x: bx, y: 1.5, w: cw, h: 2.8,
    fill: { color: C.light }, shadow: mkShadow(),
  });
  s.addText("BEFORE: BY MODALITY", {
    x: bx + 0.3, y: 1.6, w: cw - 0.6, h: 0.4,
    fontSize: 13, fontFace: FONT_B, color: C.red, bold: true, margin: 0,
  });

  const modalities = ["Text Generation", "Image Generation", "Code Generation", "Speech / Audio"];
  s.addText(modalities.map((t, i) => ({
    text: t,
    options: { bullet: true, breakLine: i < modalities.length - 1, fontSize: 12, fontFace: FONT_B, color: C.grayDark },
  })), {
    x: bx + 0.3, y: 2.1, w: cw - 0.6, h: 2.0,
    paraSpaceAfter: 8,
  });

  // After card
  s.addShape(pres.shapes.RECTANGLE, {
    x: ax, y: 1.5, w: cw, h: 2.8,
    fill: { color: C.light }, shadow: mkShadow(),
  });
  s.addText("NOW: BY USE CASE", {
    x: ax + 0.3, y: 1.6, w: cw - 0.6, h: 0.4,
    fontSize: 13, fontFace: FONT_B, color: C.green, bold: true, margin: 0,
  });

  const useCases = [
    "Legal — Harvey (custom LLMs for elite law firms)",
    "Enterprise Search — Glean (workspace indexing)",
    "Companionship — Character & Ava",
    "Multi-modal, end-to-end workflows",
  ];
  s.addText(useCases.map((t, i) => ({
    text: t,
    options: { bullet: true, breakLine: i < useCases.length - 1, fontSize: 12, fontFace: FONT_B, color: C.grayDark },
  })), {
    x: ax + 0.3, y: 2.1, w: cw - 0.6, h: 2.0,
    paraSpaceAfter: 8,
  });

  // Arrow between
  s.addShape(pres.shapes.LINE, {
    x: 4.85, y: 2.9, w: 0.3, h: 0,
    line: { color: C.dark, width: 2 },
  });

  s.addText("The shift from modality to use case reflects the broader transition from technology hammer to value delivery — applications are increasingly multi-modal by nature.", {
    x: 0.8, y: 4.6, w: 8.4, h: 0.7,
    fontSize: 12, fontFace: FONT_B, color: C.gray, italic: true, margin: 0,
  });
}

// ============================================================
// SLIDE 8 — Key Takeaways
// ============================================================
{
  const s = pres.addSlide();
  s.background = { color: C.dark };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.green } });

  s.addText("Key Takeaways:\nWhat Separates Winners in Act Two", {
    x: 0.8, y: 0.35, w: 8.4, h: 0.95,
    fontSize: 24, fontFace: FONT_H, color: C.white, bold: true, margin: 0,
  });

  const takeaways = [
    { num: "01", text: "Retention is the critical challenge — AI-first apps at 14% median vs. 51% for incumbents, a 3.6× gap" },
    { num: "02", text: "Foundation models should be a component, not the whole product — thin wrappers won't survive" },
    { num: "03", text: "Multi-modal, workflow-integrated solutions with new editing interfaces will win" },
    { num: "04", text: "The >$1B revenue milestone proves real demand exists despite hype-cycle skepticism" },
    { num: "05", text: "Companies solving end-to-end human problems — not demoing cool tech — will define Act 2" },
  ];

  takeaways.forEach((t, i) => {
    const y = 1.6 + i * 0.75;
    s.addText(t.num, {
      x: 0.8, y: y, w: 0.6, h: 0.55,
      fontSize: 22, fontFace: FONT_H, color: C.green, bold: true, margin: 0, valign: "top",
    });
    s.addText(t.text, {
      x: 1.5, y: y, w: 7.7, h: 0.55,
      fontSize: 13, fontFace: FONT_B, color: "CBD5E0", margin: 0, valign: "top",
    });
  });
}

// ============================================================
// SAVE
// ============================================================
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Saved to /app/output/final_deck.pptx"))
  .catch(err => { console.error(err); process.exit(1); });

